 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    run = next((c for c in range(w - 2)
                if all(grid[0][c + k] != 0 for k in range(3))), None)
    if run is None:
        return out
    colors = grid[0][run:run + 3]
    # Middle marker color forms a full vertical ray.
    for r in range(h):
        out[r][run + 1] = colors[1]
    # Each outer color follows an L-shaped path to its matching singleton:
    # source column down/up to target row, then along that row to target.
    for idx in (0, 2):
        color = colors[idx]
        sr, sc = 0, run + idx
        targets = [(r, c) for r in range(h) for c in range(w)
                   if grid[r][c] == color and (r, c) != (sr, sc)]
        if not targets:
            continue
        tr, tc = targets[0]
        for r in range(min(sr, tr), max(sr, tr) + 1):
            out[r][sc] = color
        for c in range(min(sc, tc), max(sc, tc) + 1):
            out[tr][c] = color
    return out
